$:set -euo pipefail
node <<'NODE'

"use strict";
const fs=require("fs"),cp=require("child_process"),crypto=require("crypto");
const root="workspaces/codespace-mcp-srs-design/", mark=String.fromCharCode(96);
const original=fs.readFileSync(root+"AGENTS.md","utf8"),doc=JSON.parse(original);
if(doc.version!=="1.0.0"||doc.tasks.length!==15)throw Error("Unexpected bootstrap version or stage count");
if(!fs.readFileSync("AGENTS.md","utf8").includes("INTEGRATION-01"))throw Error("Governing AGENTS.md missing or invalid");
const requirements=JSON.parse(fs.readFileSync("terminals_requirements.json","utf8"));
if(!requirements.requirements.some(x=>x.id==="PROJ-001"))throw Error("SRS projection requirement missing");
const readme=fs.readFileSync(root+"README.md","utf8");
doc.version="2.0.0";
doc.workflow={
 ordering:"sequential_with_targeted_rework_only",
 task_status_values:["pending","in_progress","blocked","verified"],
 advance_when:"stage_exit_checks_verified",
 on_block:"record_material_blocker_in_relevant_document",
 on_revision:"recheck_only_affected_requirements_contracts_tests_and_projection",
 evidence:"source_revision_and_rationale_for_material_claims",
 optimization:"no_separate_inventory_feasibility_report_risk_register_duplicate_review_or_handoff_report"
};
doc.tasks=[
 {id:"DES-01",order:1,depends_on:[],action:"confirm_authority_and_material_constraints",scope:["read_governing_instructions_and_verify_workspace","inspect_existing_components_only_where_reused","verify_external_constraints_only_where_decision_critical"],outputs:["material_constraints_in_SRS_or_ARCHITECTURE"],exit:["authority_known","critical_assumptions_recorded"]},
 {id:"DES-02",order:2,depends_on:["DES-01"],action:"specify_requirements_and_semantic_projection",scope:["system_boundary_and_operating_modes","functional_and_nonfunctional_requirements","authorization_and_security","state_ordering_nonces_receipts_and_recovery","atomic_acceptance_conditions","semantics_first_machine_projection_with_provenance"],outputs:["SRS.md","SRS.agent.json"],exit:["requirements_testable_and_cover_stated_system","projection_preserves_source_meaning_and_revision"]},
 {id:"DES-03",order:3,depends_on:["DES-02"],action:"design_architecture_and_interface_contracts",scope:["Codespaces_and_Node_MCP_components","MCP_transport_tools_resources_and_authentication","terminal_PTY_filesystem_and_Git","lifecycle_start_stop_reconnect_and_failure_recovery","workspace_isolation_and_secrets","decisions_alternatives_and_material_risks_within_ARCHITECTURE"],outputs:["ARCHITECTURE.md","INTERFACES.md"],exit:["components_and_flows_defined","typed_inputs_outputs_errors_permissions_and_trust_boundaries_defined","material_tradeoffs_recorded"]},
 {id:"DES-04",order:4,depends_on:["DES-03"],action:"define_acceptance_and_verification",scope:["requirements_to_test_mapping","MCP_and_terminal_IO","authorization_isolation_and_security","persistence_restart_recovery_idempotency","execution_receipts_and_independent_postcondition_readback"],outputs:["VERIFICATION-PLAN.md"],exit:["critical_requirements_have_test_oracles","pass_fail_blocked_not_run_distinct"]},
 {id:"DES-05",order:5,depends_on:["DES-04"],action:"perform_single_consistency_and_readiness_check",scope:["validate_JSON_and_document_links","trace_requirements_contracts_and_tests","record_unresolved_blockers_in_existing_documents","confirm_implementation_requires_separate_authorization"],outputs:["validated_design_baseline_no_separate_handoff_report"],exit:["versions_and_cross_references_consistent","design_ready_or_specific_blockers_recorded","no_implementation_executed"]}
];
doc.deliverables.required=["SRS.md","SRS.agent.json","ARCHITECTURE.md","INTERFACES.md","VERIFICATION-PLAN.md"];
doc.deliverables.acceptance="testable_traceable_consistent_with_explicit_blockers_and_separate_implementation_authorization";
doc.deliverables.status="not_yet_created";
doc.change_log=[{version:"2.0.0",replaces:"1.0.0",reason:"consolidate_15_stages_into_5_high_value_outcome_stages",risk_decision_location:"ARCHITECTURE.md",acceptance_evidence_location:"VERIFICATION-PLAN.md"}];
const remove="- "+mark+"DECISIONS-AND-RISKS.md"+mark+" — alternatives, assumptions, unresolved questions and constraints.\n";
if(!readme.includes(remove))throw Error("Unexpected README baseline");
const section="## Design procedure\n\nThe five-stage bootstrap procedure in "+mark+"AGENTS.md"+mark+" covers: (1) authority and material constraints, (2) requirements and semantic projection, (3) architecture and interfaces including decisions and risks, (4) verification, and (5) one consistency/readiness check. There is no separate inventory, feasibility report, risk register, or handoff report. These subjects remain addressed where relevant in the required artifacts.\n\n";
const nextReadme=readme.replace(remove,"").replace("## Working rules",section+"## Working rules");
const edits=[["AGENTS.md",JSON.stringify(doc,null,2)+"\n"],["README.md",nextReadme]];
function fetch(path){return JSON.parse(cp.execFileSync("gh",["api","repos/BestNameYet/Terminals/contents/"+path],{encoding:"utf8"}))}
for(const [name,content] of edits){
 const path=root+name;
 const remote=fetch(path);
 if(Buffer.from(remote.content.replace(/\s/g,""),"base64").toString("utf8")!==fs.readFileSync(path,"utf8"))throw Error("Remote version changed: "+path);
 const payload={message:"docs(codespace-mcp): streamline design bootstrap to five stages",content:Buffer.from(content).toString("base64"),sha:remote.sha,branch:"main"};
 const put=JSON.parse(cp.execFileSync("gh",["api","-X","PUT","repos/BestNameYet/Terminals/contents/"+path,"--input","-"],{encoding:"utf8",input:JSON.stringify(payload)}));
 const after=fetch(path);
 if(Buffer.from(after.content.replace(/\s/g,""),"base64").toString("utf8")!==content)throw Error("Readback mismatch: "+path);
 console.log(JSON.stringify({path,commit:put.commit.sha,sha256:crypto.createHash("sha256").update(content).digest("hex"),verified:true}));
}
const final=JSON.parse(Buffer.from(fetch(root+"AGENTS.md").content.replace(/\s/g,""),"base64").toString("utf8"));
if(final.tasks.length!==5||final.deliverables.required.length!==5||final.tasks.some((x,i)=>x.order!==i+1))throw Error("Final stage validation failed");
console.log("VALIDATED stages=5 artifacts=5 version="+final.version);

NODE
